import { useEffect, useState } from 'react'
import { supabase } from '../lib/supabase'
import { useAuth } from '../context/AuthContext'

const EMPTY = { name: '', buy_price: '', sell_price: '', quantity: '' }

export default function Products() {
  const user = useAuth()
  const [products, setProducts] = useState([])
  const [form, setForm] = useState(EMPTY)
  const [showForm, setShowForm] = useState(false)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')

  async function load() {
    const { data } = await supabase.from('products').select('*').eq('user_id', user.id).order('name')
    setProducts(data || [])
  }

  useEffect(() => { load() }, [])

  async function handleAdd(e) {
    e.preventDefault()
    setError('')
    setLoading(true)
    const { error } = await supabase.from('products').insert({
      user_id: user.id,
      name: form.name.trim(),
      buy_price: Number(form.buy_price),
      sell_price: Number(form.sell_price),
      quantity: Number(form.quantity),
    })
    if (error) { setError(error.message); setLoading(false); return }
    setForm(EMPTY)
    setShowForm(false)
    await load()
    setLoading(false)
  }

  const fmt = n => new Intl.NumberFormat('fr-GN').format(n)

  return (
    <div className="page pb-nav">
      <div className="page-header">
        <h1 className="page-title">📦 Stock</h1>
      </div>

      {!showForm ? (
        <button className="btn btn-green" onClick={() => setShowForm(true)}>
          + Ajouter un produit
        </button>
      ) : (
        <div className="card">
          <h2 style={{ marginBottom: 14, fontSize: 17 }}>Nouveau produit</h2>
          <form onSubmit={handleAdd}>
            <div className="form-group">
              <label>Nom du produit</label>
              <input value={form.name} onChange={e => setForm(f => ({ ...f, name: e.target.value }))}
                placeholder="Ex: Riz 25kg" required />
            </div>
            <div className="form-group">
              <label>Prix d'achat (GNF)</label>
              <input type="number" value={form.buy_price} onChange={e => setForm(f => ({ ...f, buy_price: e.target.value }))}
                placeholder="0" min="0" required />
            </div>
            <div className="form-group">
              <label>Prix de vente (GNF)</label>
              <input type="number" value={form.sell_price} onChange={e => setForm(f => ({ ...f, sell_price: e.target.value }))}
                placeholder="0" min="0" required />
            </div>
            <div className="form-group">
              <label>Quantité en stock</label>
              <input type="number" value={form.quantity} onChange={e => setForm(f => ({ ...f, quantity: e.target.value }))}
                placeholder="0" min="0" required />
            </div>
            {error && <p className="error">{error}</p>}
            <button className="btn btn-green" type="submit" disabled={loading}>
              {loading ? '...' : 'Enregistrer'}
            </button>
            <button className="btn btn-gray mt-12" type="button" onClick={() => { setShowForm(false); setError('') }}>
              Annuler
            </button>
          </form>
        </div>
      )}

      <div className="mt-20">
        {products.length === 0
          ? <p className="empty">Aucun produit. Ajoutez votre premier article.</p>
