          <form onSubmit={handleAdd}>
            <div className="form-group">
              <label>Nom du client</label>
              <input value={form.client_name} onChange={e => setForm(f => ({ ...f, client_name: e.target.value }))}
                placeholder="Ex: Fatoumata Bah" required />
            </div>
            <div className="form-group">
              <label>Montant (GNF)</label>
              <input type="number" value={form.amount} onChange={e => setForm(f => ({ ...f, amount: e.target.value }))}
                placeholder="0" min="1" required />
            </div>
            {error && <p className="error">{error}</p>}
            <button className="btn btn-blue" type="submit" disabled={loading}>
              {loading ? '...' : 'Enregistrer'}
            </button>
            <button className="btn btn-gray mt-12" type="button" onClick={() => { setShowForm(false); setError('') }}>
              Annuler
            </button>
          </form>
        </div>
      )}

      <div className="mt-20">
        {unpaid.length === 0 && paid.length === 0 && (
          <p className="empty">Aucune dette enregistrée.</p>
        )}

        {unpaid.map(d => (
          <div className="card" key={d.id}>
            <div className="card-row">
              <span className="fw-bold" style={{ fontSize: 17 }}>👤 {d.client_name}</span>
              <span className="fw-bold text-red">{fmt(d.amount)} GNF</span>
            </div>
            <div className="mt-12">
              <button className="btn btn-green btn-sm" onClick={() => markPaid(d.id)}>
                ✅ Marquer payé
              </button>
            </div>
          </div>
        ))}

        {paid.length > 0 && (
          <>
            <div className="divider" />
            <p style={{ fontSize: 13, color: 'var(--gray)', marginBottom: 10 }}>Dettes réglées</p>
            {paid.map(d => (
              <div className="card" key={d.id} style={{ opacity: 0.6 }}>
                <div className="card-row">
                  <span>👤 {d.client_name}</span>
                  <span className="badge badge-green">Payé — {fmt(d.amount)} GNF</span>
                </div>
              </div>
            ))}
          </>
        )}
      </div>
    </div>
  )
}

