import { useEffect, useState } from 'react'
import { supabase } from '../lib/supabase'
import { useAuth } from '../context/AuthContext'

const EMPTY = { client_name: '', amount: '' }

export default function Debts() {
  const user = useAuth()
  const [debts, setDebts] = useState([])
  const [form, setForm] = useState(EMPTY)
  const [showForm, setShowForm] = useState(false)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')

  async function load() {
    const { data } = await supabase.from('debts').select('*').eq('user_id', user.id)
      .order('paid').order('created_at', { ascending: false })
    setDebts(data || [])
  }

  useEffect(() => { load() }, [])

  async function handleAdd(e) {
    e.preventDefault()
    setError('')
    setLoading(true)
    const { error } = await supabase.from('debts').insert({
      user_id: user.id,
      client_name: form.client_name.trim(),
      amount: Number(form.amount),
    })
    if (error) { setError(error.message); setLoading(false); return }
    setForm(EMPTY)
    setShowForm(false)
    await load()
    setLoading(false)
  }

  async function markPaid(id) {
    await supabase.from('debts').update({ paid: true }).eq('id', id)
    setDebts(d => d.map(x => x.id === id ? { ...x, paid: true } : x))
  }

  const fmt = n => new Intl.NumberFormat('fr-GN').format(n)
  const unpaid = debts.filter(d => !d.paid)
  const paid = debts.filter(d => d.paid)
  const totalUnpaid = unpaid.reduce((s, d) => s + Number(d.amount), 0)

  return (
    <div className="page pb-nav">
      <div className="page-header">
        <h1 className="page-title">📋 Dettes</h1>
      </div>

      {unpaid.length > 0 && (
        <div className="card" style={{ background: 'var(--red-light)', marginBottom: 16 }}>
          <span style={{ fontSize: 14, color: 'var(--red)', fontWeight: 600 }}>Total dû: </span>
          <span className="fw-bold text-red" style={{ fontSize: 20 }}>{fmt(totalUnpaid)} GNF</span>
        </div>
      )}

      {!showForm ? (
        <button className="btn btn-blue" onClick={() => setShowForm(true)}>
          + Ajouter une dette
        </button>
      ) : (
        <div className="card">
          <h2 style={{ marginBottom: 14, fontSize: 17 }}>Nouvelle dette</h2>
          <form onSubmit={handleAdd}>
            <div className="form-group">
              <label>Nom du client</label>
              <input value={form.client_name} onChange={e => setForm(f => ({ ...f, client_name: e.target.value }))}
                placeholder="Ex: Fatoumata Bah" required />
            </div>
            <div className="form-group">
              <label>Montant (GNF)</label>
              <input type="number" value={form.amount} onChange={e => setForm(f => ({ ...f, amount: e.target.value }))}
                placeholder="0" min="1" required />
            </div>
            {error && <p className="error">{error}</p>}
            <button className="btn btn-blue" type="submit" disabled={loading}>
              {loading ? '...' : 'Enregistrer'}
            </button>
            <button className="btn btn-gray mt-12" type="button" onClick={() => { setShowForm(false); setError('') }}>
              Annuler
            </button>
          </form>
        </div>
      )}

      <div className="mt-20">
        {unpaid.length === 0 && paid.length === 0 && (
          <p className="empty">Aucune dette enregistrée.</p>
        )}

        {unpaid.map(d => (
          <div className="card" key={d.id}>
            <div className="card-row">
              <span className="fw-bold" style={{ fontSize: 17 }}>👤 {d.client_name}</span>
              <span className="fw-bold text-red">{fmt(d.amount)} GNF</span>
            </div>
            <div className="mt-12">
              <button className="btn btn-green btn-sm" onClick={() => markPaid(d.id)}>
                ✅ Marquer payé
              </button>
            </div>
          </div>
        ))}

        {paid.length > 0 && (
          <>
