const [products, setProducts] = useState([])

input.newStr:
async function handleSell(e) {
  e.preventDefault()
  if (submitting.current) return
  setError('')
  if (!selectedProduct) return
  const qty = Number(form.quantity)
  if (qty <= 0) { setError('Quantité invalide'); return }
  if (selectedProduct.quantity < qty) { setError('Stock insuffisant'); return }

  submitting.current = true
  setLoading(true)

  const salePayload = {
    user_id: user.id,
    product_id: selectedProduct.id,
    product_name: selectedProduct.name,
    quantity: qty,
    unit_price: selectedProduct.sell_price,
    total,
    payment_type: form.payment_type,
    client_name: form.client_name || null,
  }
  const debtPayload = form.payment_type === 'credit' ? {
    user_id: user.id,
    client_name: form.client_name || 'Client inconnu',
    amount: total,
  } : null

  if (!navigator.onLine) {
    // Queue for later sync
    addToQueue({
      salePayload,
      productId: selectedProduct.id,
      newQuantity: selectedProduct.quantity - qty,
      debtPayload,
    })
    setForm(EMPTY)
    setShowForm(false)
    submitting.current = false
    setLoading(false)
    return
  }

  const { data: saleData, error: saleErr } = await supabase
    .from('sales').insert(salePayload).select().single()

  if (saleErr) {
    setError(saleErr.message.includes('fetch') ? 'Erreur réseau. Vérifiez votre connexion.' : saleErr.message)
    submitting.current = false
    setLoading(false)
    return
  }

  await supabase.from('products').update({ quantity: selectedProduct.quantity - qty }).eq('id', selectedProduct.id)

  if (debtPayload) {
    await supabase.from('debts').insert({ ...debtPayload, sale_id: saleData.id })
  }

  setForm(EMPTY)
  setShowForm(false)
  await load()
  submitting.current = false
  setLoading(false)
}

